const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-105.503, 35.759]);
  const region = point.buffer(5000); // 5km radius around the point

  const date1Start = '2022-04-19';
  const date1End = '2022-04-20';
  const date2Start = '2022-04-23';
  const date2End = '2022-04-24';

  // 2. Data Acquisition & Check
  // Try Sentinel-2 first
  let col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate(date1Start, date1End);

  let col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filterDate(date2Start, date2End);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`April 19 Images: ${size1}`);
  console.log(`April 23 Images: ${size2}`);

  // Fallback to Landsat 8/9 if Sentinel-2 not available
  if (size1 === 0 || size2 === 0) {
    col1 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'))
      .filterBounds(region)
      .filterDate(date1Start, date1End);

    col2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'))
      .filterBounds(region)
      .filterDate(date2Start, date2End);

    const ls_size1 = await col1.size().getInfo();
    const ls_size2 = await col2.size().getInfo();

    console.log(`Landsat April 19: ${ls_size1}, April 23: ${ls_size2}`);

    if (ls_size1 === 0 || ls_size2 === 0) {
      console.log('No data available for both dates.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  function calculateNBR(image) {
    const nir = image.select('B8');
    const swir2 = image.select('B12');
    return nir.subtract(swir2).divide(nir.add(swir2)).rename('NBR');
  }

  const img1 = maskS2clouds(col1.first());
  const img2 = maskS2clouds(col2.first());

  const nbr1 = calculateNBR(img1);
  const nbr2 = calculateNBR(img2);

  // Check for valid pixels
  const count1 = await nbr1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  const count2 = await nbr2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  console.log(`Valid pixels April 19: ${count1}, April 23: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation - Detect burn scars (NBR < 0.1 indicates burned area)
  const burned1 = nbr1.lt(0.1);
  const burned2 = nbr2.lt(0.1);

  const burnArea1 = await burned1.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  const burnArea2 = await burned2.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NBR').getInfo();

  // 5. Validation & Final Answer
  if (burnArea1 === null || burnArea2 === null || isNaN(burnArea1) || isNaN(burnArea2)) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  const area1_km2 = (burnArea1 / 1e6).toFixed(2);
  const area2_km2 = (burnArea2 / 1e6).toFixed(2);

  console.log(`Burn scar area April 19: ${area1_km2} km²`);
  console.log(`Burn scar area April 23: ${area2_km2} km²`);
  console.log(`Change: ${(area2_km2 - area1_km2).toFixed(2)} km²`);

  if (burnArea2 > burnArea1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
